function check(ok,message){if(!ok)throw new Error(message);}
function key(id){return String(id||'').replace(/-/g,'').toLowerCase();}
function title(p){return Object.values(p.properties||{}).filter(v=>v.type==='title').flatMap(v=>v.title||[]).map(t=>t.plain_text??t.text?.content??'').join('');}
function stable(v){return Array.isArray(v)?v.map(stable):v&&typeof v==='object'?Object.fromEntries(Object.keys(v).sort().map(k=>[k,stable(v[k])])):v;}
function snapshot(w){
 check(w&&typeof w.id==='string'&&typeof w.name==='string'&&Array.isArray(w.nodes)&&w.connections&&typeof w.connections==='object','Invalid workflow');
 return {name:w.name,nodes:w.nodes,pinData:w.pinData||{},connections:w.connections,active:w.active===true,settings:{executionOrder:'v1',binaryMode:'separate',...(w.settings||{})},id:w.id,tags:w.tags||[],nodeGroups:w.nodeGroups||[]};
}
function markdown(w){const text=JSON.stringify(snapshot(w),null,2);const fence='`'.repeat(Math.max(3,...(text.match(/`+/g)||[]).map(s=>s.length+1)));return fence+'json\n'+text+'\n'+fence;}
function plan(catalog,children,workflows){
 const sources=new Map(workflows.filter(w=>!w.isArchived).map(w=>[w.id,w])),items=[],skipped=[];
 for(const p of catalog){
  if(p.archived||p.is_archived||p.in_trash)continue;
  check(key(p.parent?.data_source_id)==='YOUR_NOTION_DATA_SOURCE_ID','Unexpected catalog parent');
  const url=p.properties?.['Apri n8n']?.url;
  const m=typeof url==='string'&&url.match(/^https:\/\/n8n\.example\.com\/workflow\/([A-Za-z0-9_-]+)\/?(?:[?#][^\r\n]*)?$/);
  const source=m&&sources.get(m[1]);
  if(!source){skipped.push({pageId:p.id,name:title(p),reason:!url?'No n8n link':m?'Source workflow deleted or archived':'Invalid n8n link'});continue;}
  const found=children.filter(c=>!c.archived&&!c.is_archived&&!c.in_trash&&key(c.parent?.page_id)===key(p.id)&&title(c)==='Workflow');
  check(found.length<2,'Duplicate Workflow subpages for '+title(p));
  const newMarkdown=markdown(source);
  check(new TextEncoder().encode(JSON.stringify({type:'replace_content',replace_content:{new_str:newMarkdown}})).length<490000,'Workflow exceeds Notion request limit: '+source.name);
  items.push({workflowId:source.id,name:source.name,pageId:p.id,childId:found[0]?.id||'',source:snapshot(source),newMarkdown});
 }
 check(items.length||skipped.length,'Catalog is empty');
 return {items,skipped,total:items.length+skipped.length};
}
